const items = $input.all().map(i => i.json).flat();
const due = Array.isArray(items) ? items : [];
const lines = due.map(f => `• ${f.business_name || f.contact_id}: ${f.reason || 'follow-up'} (${f.due_at || ''})`);
return [{ json: { count: due.length, digest: due.length ? `SELL AGENT — ${due.length} follow-up(s) today:\n` + lines.join('\n') : 'SELL AGENT — no follow-ups due today.' } }];
